import type { MediaReference } from "../settings/types.js";

/**
 * A profile link is the shared shape for site and byline links.
 */
export interface ProfileLink {
	/** Stable ID within its list, generated by the admin or client. */
	id: string;
	/** Platform key from the built-in registry, or "custom". */
	platform: string;
	/** Display label. Required for "custom", optional otherwise. */
	label?: string;
	/** URL, handle or account ID, as the editor entered it. */
	value: string;
	/** Include in Schema.org `sameAs`. Applies only when `value` resolves to an https URL. */
	sameAs: boolean;
	/** Emit `<link rel="me">`. Applies only when `value` resolves to an https URL. */
	relMe: boolean;
}

/** Input shape when writing a profile link (`id` can be generated if omitted). */
export interface ProfileLinkInput {
	id?: string;
	platform: string;
	label?: string;
	value: string;
	sameAs?: boolean;
	relMe?: boolean;
}

/** Postal address structure conforming to Schema.org PostalAddress */
export interface PostalAddress {
	streetAddress?: string;
	postalCode?: string;
	addressLocality?: string;
	addressRegion?: string;
	/** ISO 3166-1 alpha-2 country code (e.g. "CH", "US") */
	addressCountry?: string;
}

/** Structured business identifier (VAT, DUNS, LEI, etc.) */
export interface OrganizationIdentifier {
	propertyID: string;
	value: string;
}

/** Organization policy page links */
export interface OrganizationPolicies {
	publishingPrinciples?: string;
	correctionsPolicy?: string;
	ethicsPolicy?: string;
	diversityPolicy?: string;
	ownershipFundingInfo?: string;
	actionableFeedbackPolicy?: string;
}

/**
 * Publisher identity stored in `site:identity`.
 * Describes the Organization or Person publishing the site.
 */
export interface SiteIdentity {
	type: "Organization" | "Person";
	/** Legal or display name. Falls back to the site title. */
	name?: string;
	alternateName?: string;
	description?: string;
	/** Falls back to `site:logo`. */
	logo?: MediaReference;
	/** Absolute https URL used as the entity's `url`. Defaults to the site URL. */
	url?: string;
	email?: string;
	telephone?: string;
	address?: PostalAddress;
	/** ISO 3166-1 alpha-2 codes or region names. */
	areaServed?: string[];
	foundingDate?: string;
	/** Organization only: business registration identifiers. */
	identifiers?: OrganizationIdentifier[];
	/** Organization only: absolute https URLs of policy pages. */
	policies?: OrganizationPolicies;
	/** Person only: professional job title. */
	jobTitle?: string;
	/** Person only: the byline that represents the site owner. */
	bylineId?: string;
	/** List of profile and social links. */
	links: ProfileLink[];
}

/** Partial write shape for `site:identity`. */
export interface SiteIdentityInput extends Omit<Partial<SiteIdentity>, "logo" | "links"> {
	type?: "Organization" | "Person";
	logo?: MediaReference | null;
	links?: ProfileLinkInput[];
}
